class RefinementApplied4(RootModel[RefinementApplied | RefinementApplied6 | RefinementApplied7]):
    root: Annotated[
        RefinementApplied | RefinementApplied6 | RefinementApplied7, Field(discriminator="scope")
    ]

    def __getattr__(self, name: str) -> Any:
        """Proxy attribute access to the wrapped type."""
        if name.startswith("_"):
            raise AttributeError(name)
        return getattr(self.root, name)


