class Forecast1(AdCPBaseModel):
    model_config = ConfigDict(
        extra="allow",
    )
    points: Annotated[
        list[Point1],
        Field(
            description="Forecasted delivery data points. For spend curves (default), points at ascending budget levels show how metrics scale with spend. For availability forecasts, points represent total available inventory independent of budget. See forecast_range_unit for interpretation.",
            min_length=1,
        ),
    ]
    forecast_range_unit: ForecastRangeUnit | None = None
    method: ForecastMethod
    currency: Annotated[
        str,
        Field(
            description="ISO 4217 currency code for monetary values in this forecast (spend, budget)"
        ),
    ]
    demographic_system: DemographicSystem | None = None
    demographic: Annotated[
        str | None,
        Field(
            description="Target demographic code within the specified demographic_system. For Nielsen: P18-49, M25-54, W35+. For BARB: ABC1 Adults, 16-34. For AGF: E 14-49.",
            examples=["P18-49", "A25-54", "W35+", "M18-34"],
        ),
    ] = None
    measurement_source: Annotated[
        str | None,
        Field(
            description="Third-party measurement provider whose data was used to produce this forecast. Distinct from demographic_system, which specifies demographic notation — measurement_source identifies whose data produced the forecast numbers. Should be present when measured_impressions is used. Lowercase slug format.",
            examples=[
                "nielsen",
                "videoamp",
                "comscore",
                "geopath",
                "barb",
                "agf",
                "oztam",
                "kantar",
                "barc",
                "route",
                "rajar",
                "triton",
            ],
            max_length=64,
            pattern="^[a-z0-9_]+$",
        ),
    ] = None
    reach_unit: ReachUnit | None = None
    generated_at: Annotated[
        AwareDatetime | None, Field(description="When this forecast was computed")
    ] = None
    valid_until: Annotated[
        AwareDatetime | None,
        Field(
            description="When this forecast expires. After this time, the forecast should be refreshed. Forecast expiry does not affect proposal executability."
        ),
    ] = None
    ext: Annotated[
        dict[str, Any] | None,
        Field(
            description="Extension object for platform-specific, vendor-namespaced parameters. Extensions are always optional and must be namespaced under a vendor/platform key (e.g., ext.gam, ext.roku). Used for custom capabilities, partner-specific configuration, and features being proposed for standardization.",
            title="Extension Object",
        ),
    ] = None


